enum Shape { case circle(Int), box(Int) }
let s = Shape.circle(2)
if case .circle(let r) = s {
    print("radius", r)
}

enum Node { case file(String), dir([Node]) }
let root = Node.dir([.file("a"), .dir([])])
if case .dir(let kids) = root {
    print(kids.count)
}

indirect enum Chain {
    case end
    case link(Int, Chain)
}
let c = Chain.link(1, .link(2, .end))
if case .link(let n, _) = c { print(n) }

